# Python Pro track: testing, writing real code, concurrency, performance, statistics, modelling by hand.
# Exec'd inside lessons.py after the helpers (S, Sd, Q, QE, QC, W, PM) and lessons_py2.py (Sh, Qh, QEh, Wh).
# Examples run with plain CPython at build time AND must also run in the browser harness (check with the throwaway script).
# asyncio cannot run in the browser tab, so those screens are Sd with an output block computed at build time (see _with_out).

def _with_out(code):
    """Code for a display-only screen: the code plus a comment block holding what it really printed at build time."""
    got = _out(code)
    return code.rstrip() + "\n\n# --- what it prints ---\n" + "\n".join("# " + l for l in got.splitlines())

_RZ = "def _raises(fn, exc=Exception):\n    try:\n        fn()\n    except exc:\n        return True\n    return False\n\n"

# =====================================================================================================
# 1. TESTING
# =====================================================================================================
PM("py-testing", "Python Pro", "Testing with assert and pytest",
   "Code you cannot test is code you cannot change safely; every real team expects tests, and interviewers read them as a sign you can ship.",
 [
 S("assert: a claim the computer checks",
   "<code>assert</code> says: \"this must be true\". If it is, nothing happens. If it is not, Python stops with an <code>AssertionError</code>. You can add a message after a comma. That is the whole idea of a test: write down what should be true, let the computer check it. (A word you will see: <b>bug</b> = the code does not do what you meant.) Use <code>assert</code> for tests and for \"this can never happen\" checks. Do <b>not</b> use it to check what a user typed: assertions can be switched off when Python runs with the <code>-O</code> flag, so use <code>raise ValueError</code> for that.",
   'def double(x):\n    return x + 2      # a bug: should be x * 2\n\nassert double(2) == 4\nprint("check 1 passed")\n\ntry:\n    assert double(5) == 10, "double(5) should be 10"\nexcept AssertionError as e:\n    print("check 2 failed:", e)', run=True,
   q=QE("What happens here?", 'items = ["a", "b", "c"]\nassert len(items) == 4, "expected four items"',
        "AssertionError", ["Nothing, it prints nothing", "An AssertionError with the message: expected four items", "A ValueError"], 1,
        "len(items) is 3, so the claim is False and assert raises AssertionError carrying your message. Note that check 1 above passed only by luck: 2 + 2 and 2 * 2 are both 4, which is why one test is never enough.")),
 S("Arrange, act, assert",
   "A good test has three parts. <b>Arrange</b>: set up the inputs. <b>Act</b>: call the one thing you are testing. <b>Assert</b>: check the result. Give the test a name that reads like a sentence about behaviour. Keep each test to one idea so that when it fails, the name already tells you what broke. Tests are plain functions here, and we call them ourselves.",
   'def apply_discount(price, percent):\n    return price - price * percent / 100\n\ndef test_discount_takes_percent_off_the_price():\n    # arrange\n    price = 200\n    percent = 25\n    # act\n    result = apply_discount(price, percent)\n    # assert\n    assert result == 150\n\ntest_discount_takes_percent_off_the_price()\nprint("passed")', run=True,
   q=QC("In the test above, which line is the <b>act</b> step?", ["<code>result = apply_discount(price, percent)</code>", "<code>price = 200</code>", "<code>assert result == 150</code>"], 0,
        "The act step is the single call to the code under test. Setting up the numbers is arrange, and the final check is assert.")),
 S("Edge cases: where bugs live",
   "Most bugs hide at the edges, not in the middle. For any function, ask: what is the <b>smallest</b> input (empty list, zero, empty string)? The <b>one-item</b> input? A <b>negative</b> or <b>duplicate</b> value? The values <b>just below, at and just above</b> a limit (a boundary)? The wrong type? Below, the happy path works and the empty list quietly breaks.",
   'def average(nums):\n    return sum(nums) / len(nums)\n\nprint(average([2, 4, 6]))\nprint(average([5]))\nprint(average([-2, 2]))\ntry:\n    print(average([]))\nexcept ZeroDivisionError:\n    print("empty list crashes")', run=True,
   q=Q("What does this show?", 'def average(nums):\n    return sum(nums) / len(nums)\n\nprint(average([-2, 2]))', ["0.0", "0", "ZeroDivisionError"],
       "The sum is 0 and there are 2 items, so 0 / 2 is 0.0 (division with / always gives a float). It is a good edge case because a careless check like \"if not result\" would treat 0.0 as missing.")),
 S("A table of cases and a check() that returns failures",
   "Instead of one assert per line, keep a <b>table of cases</b>: inputs and the expected answer. Loop over it and collect what went wrong. This is the idea behind \"parametrised\" tests: <b>one test body, many data rows</b>. Returning a list of failure messages (empty list means all good) is more useful than stopping at the first failure, because you see every problem at once.",
   'def clamp(x, lo, hi):\n    return max(lo, min(x, hi))\n\nCASES = [\n    ((5, 0, 10), 5),     # inside\n    ((-3, 0, 10), 0),    # below\n    ((14, 0, 10), 10),   # above\n    ((0, 0, 10), 0),     # on the lower edge\n    ((10, 0, 10), 10),   # on the upper edge\n]\n\ndef check():\n    failures = []\n    for args, want in CASES:\n        got = clamp(*args)\n        if got != want:\n            failures.append(f"clamp{args}: wanted {want}, got {got}")\n    return failures\n\nprint(check())', run=True,
   q=Q("Someone \"fixes\" clamp to this version. How many cases fail?",
       'def clamp(x, lo, hi):\n    return min(lo, max(x, hi))\n\nCASES = [((5, 0, 10), 5), ((-3, 0, 10), 0), ((14, 0, 10), 10), ((0, 0, 10), 0), ((10, 0, 10), 10)]\nfailures = [a for a, want in CASES if clamp(*a) != want]\nprint(len(failures))',
       ["0", "3", "5"], "min(lo, max(x, hi)) can never be above lo, so it returns 0 for everything: only the two cases whose answer is 0 pass. Three fail. A table of cases caught it instantly.")),
 Sd("pytest: the same ideas with less typing",
    "<b>pytest</b> is the standard test tool (<code>pip install pytest</code>, then run <code>pytest</code> in the terminal). It cannot run inside this page, so this screen is for reading. The conventions are what matter: test files are named <code>test_*.py</code>, test functions are named <code>test_*</code>, and you use plain <code>assert</code>. pytest rewrites asserts so a failure shows both values. <code>@pytest.mark.parametrize</code> turns a table of cases into separate tests, <code>pytest.raises</code> checks that an error is raised, and a <b>fixture</b> is a function that builds shared set-up data and is handed to any test that names it as a parameter. The terminal shows a dot per passing test and an F per failure, then a summary.",
    '# file: test_clamp.py   (name starts with test_)\nimport pytest\nfrom clamp import clamp      # clamp.py holds the real function\n\ndef test_inside_range_is_unchanged():\n    assert clamp(5, 0, 10) == 5\n\n@pytest.mark.parametrize("x, want", [(-3, 0), (14, 10), (0, 0), (10, 10)])\ndef test_outside_range_is_cut_to_the_edge(x, want):\n    assert clamp(x, 0, 10) == want\n\ndef test_bad_range_raises():\n    # assumes clamp raises ValueError when lo > hi\n    with pytest.raises(ValueError):\n        clamp(5, 10, 0)\n\n@pytest.fixture\ndef orders():\n    return [{"id": 1, "amount": 50}, {"id": 2, "amount": 70}]\n\ndef test_total(orders):          # pytest passes the fixture in by name\n    assert sum(o["amount"] for o in orders) == 120\n\n# terminal:\n#   pip install pytest\n#   pytest -q',
    q=QC("pytest finds tests by name. Which of these will it run by default?", ["<code>def test_total():</code> inside a file called <code>test_orders.py</code>", "<code>def check_total():</code> inside <code>test_orders.py</code>", "<code>def test_total():</code> inside a file called <code>helpers.py</code>"], 0,
         "Both the file (test_*.py) and the function (test_*) must match the convention. A function named check_total or a file named helpers.py is ignored, which is a classic reason for \"my tests did not run\".")),
 S("Mocking: replace the network with a fake",
   "A test must be fast and repeatable, so it should never depend on the internet, the clock or a real database. The trick: let the function <b>receive</b> the risky part (here, the function that fetches data) as a parameter, and in the test pass a <b>fake</b>. A fake that returns a fixed answer makes the test deterministic; a fake that raises lets you test the error path that is almost impossible to trigger for real. This is what \"mocking\" means. (Python also has <code>unittest.mock</code> to patch things in place, but passing the dependency in is simpler and clearer.)",
   'def describe_weather(city, fetch):\n    data = fetch(city)            # in production: a real HTTP call\n    if data["temp"] >= 30:\n        return f"{city}: hot"\n    return f"{city}: mild"\n\ndef fake_hot(city):\n    return {"temp": 35}\n\ndef fake_cool(city):\n    return {"temp": 12}\n\ndef fake_down(city):\n    raise TimeoutError("network down")\n\nprint(describe_weather("Pune", fake_hot))\nprint(describe_weather("Pune", fake_cool))\ntry:\n    describe_weather("Pune", fake_down)\nexcept TimeoutError as e:\n    print("error path:", e)', run=True,
   q=Q("What does this show?", 'def describe_weather(city, fetch):\n    data = fetch(city)\n    if data["temp"] >= 30:\n        return f"{city}: hot"\n    return f"{city}: mild"\n\nprint(describe_weather("Goa", lambda city: {"temp": 30}))',
       ["Goa: hot", "Goa: mild", "TypeError"], "The fake always returns a temperature of exactly 30, and the rule is >= 30, so it is hot. Testing the boundary value with a fake is exactly why fakes are useful.")),
 S("Test-driven bug fixing",
   "When someone reports a bug, do this: (1) write a test that <b>fails</b> and reproduces the bug, (2) fix the code, (3) watch the test pass, and keep the test forever so the bug cannot return. Here the report says: \"initials crashes when there are two spaces in a name\". First the failing check, then the fix. The fix uses <code>split()</code> with no argument, which splits on any run of whitespace and ignores empty pieces.",
   'def initials(name):\n    return "".join(w[0].upper() for w in name.split(" "))\n\nCASES = [("asha rao", "AR"), ("asha  rao", "AR"), ("", "")]\n\ndef check(fn):\n    failures = []\n    for text, want in CASES:\n        try:\n            got = fn(text)\n        except Exception as e:\n            got = type(e).__name__\n        if got != want:\n            failures.append(f"{text!r}: wanted {want!r}, got {got!r}")\n    return failures\n\nprint(check(initials))        # step 1: the tests fail\n\ndef initials_fixed(name):\n    return "".join(w[0].upper() for w in name.split())\n\nprint(check(initials_fixed))  # step 3: they pass', run=True,
   q=Q("What does this show?", 'print("a  b".split(" "))\nprint("a  b".split())', ["['a', '', 'b']\n['a', 'b']", "['a', 'b']\n['a', 'b']", "['a', '', 'b']\n['a', '', 'b']"],
       "split(\" \") cuts at every single space, so two spaces leave an empty piece, and \"\"[0] crashes with IndexError. split() with no argument treats any run of whitespace as one cut.")),
 S("Your turn: write the tests",
   "This time <b>you are the tester</b>. Below is a correct <code>leap_good</code> and several wrong versions, each with a different bug. Your job is to write <code>check_leap(fn)</code>, which takes any leap-year function and returns a list of failure messages (empty list if the function looks right). It will be graded by running your function on the correct versions (it must return <code>[]</code>) and on every buggy one (it must return something). Think about the rules, then choose years that expose each possible mistake. The years 1900 and 2000 are worth a thought.",
   q=W("Write <code>check_leap(fn)</code>. Call <code>fn(year)</code> on several years of your choice and compare with the known right answer. Return a list of strings, one per wrong answer; return <code>[]</code> if every answer is right. The rule for a leap year: divisible by 4, except years divisible by 100 are not leap, except years divisible by 400 are leap.",
       "def check_leap(fn):\n    failures = []\n    # for each (year, expected) you choose:\n    #     if fn(year) != expected: failures.append(\"...\")\n    return failures\n",
       "def check_leap(fn):\n    failures = []\n    cases = [(2023, False), (2024, True), (1900, False), (2000, True), (2100, False), (1996, True), (2019, False)]\n    for year, want in cases:\n        got = fn(year)\n        if got != want:\n            failures.append(f\"{year}: wanted {want}, got {got}\")\n    return failures\n",
       exprs=[("accepts the correct version", "check_leap(leap_good) == []"),
              ("accepts a differently written correct version", "check_leap(leap_good2) == []"),
              ("returns a list", "type(check_leap(leap_good)) is list"),
              ("rejects the version that forgets the 400 rule", "len(check_leap(leap_bug_no400)) > 0"),
              ("rejects the version that forgets the 100 rule", "len(check_leap(leap_bug_no100)) > 0"),
              ("rejects the version that only checks 400", "len(check_leap(leap_bug_only400)) > 0"),
              ("rejects the version that gets 4 backwards", "len(check_leap(leap_bug_inverted)) > 0")],
       hint="Pick at least one ordinary leap year, one ordinary non-leap year, a century that is NOT leap (1900) and a century that IS leap (2000).",
       prelude="def leap_good(year):\n    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)\n\ndef leap_good2(year):\n    if year % 400 == 0:\n        return True\n    if year % 100 == 0:\n        return False\n    return year % 4 == 0\n\ndef leap_bug_no400(year):\n    return year % 4 == 0 and year % 100 != 0\n\ndef leap_bug_no100(year):\n    return year % 4 == 0\n\ndef leap_bug_only400(year):\n    return year % 400 == 0\n\ndef leap_bug_inverted(year):\n    return year % 4 != 0\n")),
 S("Final task: write the function so the hidden tests pass",
   "Now the other side: someone else wrote the tests and you must make them pass. A <b>slug</b> is the URL-friendly version of a title: lower case, with every run of characters that are not letters or digits turned into a single dash, and no dash at either end. <code>re.sub(pattern, replacement, text)</code> replaces matches of a pattern; <code>[^a-z0-9]+</code> means \"one or more characters that are not a lowercase letter or digit\". Read the edge cases in the task before you code.",
   q=W("Write <code>slugify(title)</code>. Lower-case the text, replace every run of characters other than <code>a-z</code> and <code>0-9</code> with one <code>-</code>, and remove any <code>-</code> from the start and the end. <code>slugify('')</code> and <code>slugify('!!!')</code> give <code>''</code>.",
       "import re\n\ndef slugify(title):\n    return title\n",
       "import re\n\ndef slugify(title):\n    return re.sub(r\"[^a-z0-9]+\", \"-\", title.lower()).strip(\"-\")\n",
       exprs=[("simple", "slugify('Hello World')"),
              ("extra spaces and punctuation", "slugify('  Hello,   World!!  ')"),
              ("symbols inside the title", "slugify('C++ & Python 3.12')"),
              ("already a slug", "slugify('data-science')"),
              ("empty string", "slugify('')"),
              ("only symbols", "slugify('!!!')"),
              ("digits survive", "slugify('2024 Report')")],
       hint="re.sub(r\"[^a-z0-9]+\", \"-\", title.lower()) does the middle; .strip(\"-\") removes dashes from both ends.")),
 ])

# =====================================================================================================
# 2. WRITING REAL CODE
# =====================================================================================================
PM("py-design", "Python Pro", "Writing real code",
   "Interview code runs once; real code is read, changed and run by other people for years, and these habits are what make it safe to hand over.",
 [
 S("Type hints: say what goes in and what comes out",
   "A <b>type hint</b> is a label that tells readers (and tools) what type a value should be: <code>x: int</code> for a parameter, <code>-&gt; float</code> for what the function returns, <code>list[float]</code> for a list of floats, <code>dict[str, int]</code> for a dict from text to numbers, <code>dict | None</code> for \"a dict, or None\". The important fact: <b>Python does not enforce hints when the code runs</b>. They are documentation that editors and checkers such as <code>mypy</code> or <code>pyright</code> read to warn you before you run anything.",
   'def total_price(prices: list[float], discount: float = 0.25) -> float:\n    return sum(prices) * (1 - discount)\n\ndef find_user(user_id: int) -> dict | None:\n    users = {1: {"name": "Asha"}}\n    return users.get(user_id)\n\nprint(total_price([100.0, 50.0]))\nprint(find_user(1))\nprint(find_user(9))\n\ndef twice(x: int) -> int:\n    return x * 2\n\nprint(twice("ab"))     # a type checker would flag this; Python runs it happily', run=True,
   q=Q("What does this show?", 'def twice(x: int) -> int:\n    return x * 2\n\nprint(twice("ab"))', ["abab", "TypeError", "ab2"],
       "The hint says int, but nothing checks it at run time. \"ab\" * 2 is plain string repetition, so it prints abab. A checker like mypy would have caught it before you ran the code.")),
 S("Dataclasses and enums: name your data",
   "Passing around loose dicts and tuples invites typos. A <b>dataclass</b> is a class whose fields you just list with type hints; Python writes <code>__init__</code>, a readable <code>__repr__</code> (what <code>print</code> shows) and <code>==</code> for you. An <b>Enum</b> is a fixed set of named choices, so a status can only be one of a few known values instead of any string you mistype. For a list field you must write <code>field(default_factory=list)</code> so that each object gets its own list.",
   'from dataclasses import dataclass, field\nfrom enum import Enum\n\nclass Status(Enum):\n    PENDING = "pending"\n    PAID = "paid"\n    REFUNDED = "refunded"\n\n@dataclass\nclass Order:\n    id: int\n    amount: float\n    status: Status = Status.PENDING\n    tags: list[str] = field(default_factory=list)\n\na = Order(1, 250.0)\nb = Order(1, 250.0)\nprint(a)\nprint(a == b)\na.status = Status.PAID\nprint(a.status, a.status.value)\nprint(Status("refunded"))\ntry:\n    Status("shipped")\nexcept ValueError as e:\n    print("ValueError:", e)', run=True,
   q=QE("What happens when this class is defined?", 'from dataclasses import dataclass\n\n@dataclass\nclass Cart:\n    items: list = []',
        "ValueError", ["It works; every Cart starts with an empty list", "A ValueError: mutable default not allowed, use default_factory", "A SyntaxError"], 1,
        "A single shared [] would be reused by every Cart, so Python refuses. field(default_factory=list) builds a fresh list per object.")),
 S("f-strings: control how values print",
   "Inside <code>{ }</code> in an f-string you can add a colon and a <b>format spec</b>. <code>:.2f</code> two decimals, <code>:,</code> thousands separators, <code>:.1%</code> a fraction as a percent with one decimal, <code>:&gt;8</code> right-align in 8 characters (<code>&lt;</code> left, <code>^</code> centre), <code>:03d</code> pad an integer with zeros to width 3. <code>{x=}</code> prints the name and the value, handy for quick debugging. These specs are how you print aligned reports and money without extra libraries.",
   'price = 1234567.891\nrate = 0.256\nname = "Asha"\nn = 7\nprint(f"{price:,.2f}")\nprint(f"{rate:.1%}")\nprint(f"[{name:>8}]")\nprint(f"[{name:<8}]")\nprint(f"[{n:03d}]")\nx = 42\nprint(f"{x=}")\nprint(f"{\'item\':<8}{\'qty\':>5}")\nprint(f"{\'pen\':<8}{12:>5}")', run=True,
   q=Q("What does this show?", 'print(f"{0.256:.1%}")', ["25.6%", "0.3%", "0.26"],
       "The % spec multiplies by 100 and adds a percent sign; .1 keeps one decimal. 0.256 becomes 25.6%.")),
 S("Custom exceptions",
   "Built-in errors like <code>ValueError</code> are vague. Your own exception class says what went wrong in your domain, and callers can catch exactly that. Make one by subclassing <code>Exception</code>. Make a small <b>family</b>: a base class, then specific ones below it, so a caller can catch either the specific case or the whole family. Put useful data on the exception as attributes. <code>raise NewError(...) from e</code> keeps the original error attached as <code>__cause__</code> so nothing is lost.",
   'class PaymentError(Exception):\n    """Base class for payment problems."""\n\nclass InsufficientFunds(PaymentError):\n    def __init__(self, balance, needed):\n        super().__init__(f"balance {balance} is less than {needed}")\n        self.balance = balance\n        self.needed = needed\n\ndef pay(balance, amount):\n    if amount > balance:\n        raise InsufficientFunds(balance, amount)\n    return balance - amount\n\ntry:\n    pay(100, 250)\nexcept InsufficientFunds as e:\n    print("short by", e.needed - e.balance)\nexcept PaymentError:\n    print("some other payment problem")\n\ndef parse_amount(text):\n    try:\n        return float(text)\n    except ValueError as e:\n        raise PaymentError(f"bad amount: {text!r}") from e\n\ntry:\n    parse_amount("abc")\nexcept PaymentError as e:\n    print(e)\n    print(type(e.__cause__).__name__)', run=True,
   q=Q("What does this show? (Python uses the <b>first</b> matching except.)", 'class A(Exception):\n    pass\n\nclass B(A):\n    pass\n\ntry:\n    raise B()\nexcept A:\n    print("caught as A")\nexcept B:\n    print("caught as B")', ["caught as A", "caught as B", "caught as A\ncaught as B"],
       "B is a kind of A, so the first clause matches and the second is never reached. Put the more specific exception first.")),
 S("Context managers: always clean up",
   "A <b>context manager</b> is something you use with <code>with</code>. It guarantees set-up and clean-up, even if an error happens in the middle: closing a file, releasing a lock, committing a transaction. A class makes one with two methods: <code>__enter__</code> runs at the start (its return value goes after <code>as</code>), <code>__exit__</code> runs at the end <b>always</b>. If <code>__exit__</code> returns False the error continues upward. The shortcut is <code>@contextmanager</code> from <code>contextlib</code>: write a generator with one <code>yield</code>; code before it is set-up, code after (put it in <code>finally</code>) is clean-up.",
   'from contextlib import contextmanager\n\nclass Resource:\n    def __init__(self, name):\n        self.name = name\n    def __enter__(self):\n        print("open", self.name)\n        return self\n    def __exit__(self, exc_type, exc, tb):\n        print("close", self.name)\n        return False        # do not swallow the error\n\nwith Resource("db") as r:\n    print("using", r.name)\n\ntry:\n    with Resource("file"):\n        raise ValueError("boom")\nexcept ValueError:\n    print("error still reached us")\n\n@contextmanager\ndef opened(name):\n    print("open", name)\n    try:\n        yield name\n    finally:\n        print("close", name)\n\nwith opened("cache") as c:\n    print("using", c)', run=True,
   q=Q("What does this show?", 'class R:\n    def __enter__(self):\n        print("in")\n    def __exit__(self, *args):\n        print("out")\n        return False\n\ntry:\n    with R():\n        print("work")\n        raise KeyError("x")\nexcept KeyError:\n    print("caught")', ["in\nwork\nout\ncaught", "in\nwork\ncaught", "in\nwork\ncaught\nout"],
       "__exit__ runs before the error leaves the with block, so \"out\" prints first; then the error travels on and is caught outside.")),
 S("logging instead of print",
   "<code>print</code> is for the user of your program. <b>Logging</b> is for the people who run it. A logger gives each message a <b>level</b>: DEBUG (details for developers), INFO (normal progress), WARNING (odd but survivable), ERROR (something failed), CRITICAL (the program may stop). You set a minimum level and everything quieter is dropped, so you can turn details on while debugging without editing code. Messages can carry a name, a time and go to files. Use <code>%s</code> placeholders with the values passed after the message. In a real program you configure once at start, for example <code>logging.basicConfig(level=logging.INFO, format=...)</code>, and each module uses <code>logging.getLogger(__name__)</code>. Never log passwords or tokens. The set-up lines below are for this page.",
   'import logging, sys\n\nlog = logging.getLogger("orders")\nlog.handlers.clear()\nlog.setLevel(logging.INFO)\nh = logging.StreamHandler(sys.stdout)\nh.setFormatter(logging.Formatter("%(levelname)s %(name)s: %(message)s"))\nlog.addHandler(h)\nlog.propagate = False\n\nlog.debug("details only a developer wants")   # below INFO: dropped\nlog.info("loaded %d orders", 120)\nlog.warning("order %s has no email", "A-17")\nlog.error("could not reach the payment service")', run=True,
   q=Q("The level is set to WARNING. What does this show?", 'import logging, sys\n\nlog = logging.getLogger("q")\nlog.handlers.clear()\nlog.setLevel(logging.WARNING)\nh = logging.StreamHandler(sys.stdout)\nh.setFormatter(logging.Formatter("%(levelname)s %(message)s"))\nlog.addHandler(h)\nlog.propagate = False\n\nlog.info("started")\nlog.warning("slow")\nlog.error("failed")',
       ["WARNING slow\nERROR failed", "INFO started\nWARNING slow\nERROR failed", "ERROR failed"],
       "Levels go DEBUG < INFO < WARNING < ERROR < CRITICAL. A logger set to WARNING shows WARNING and anything above it, and drops INFO.")),
 S("Config, secrets, paths and the command line",
   "<b>Never hard-code a secret</b> (API key, password) in your code: it ends up in git and cannot be taken back. Read it from an <b>environment variable</b> (<code>os.environ.get(\"NAME\", default)</code>), set by the shell, the host or a <code>.env</code> file that is listed in <code>.gitignore</code>. Environment values are always strings, so convert with <code>int(...)</code>. Use <code>os.environ[\"NAME\"]</code> (no default) when the setting is required: a missing one fails loudly with <code>KeyError</code>. For file paths use <code>pathlib</code> instead of gluing strings: <code>Path(\"data\") / \"x.csv\"</code> with <code>.name .stem .suffix .parent</code> (and on disk <code>.exists() .read_text() .mkdir(parents=True, exist_ok=True) .glob(\"*.csv\")</code>). Here we use <code>PurePosixPath</code>, which only handles the text of a path and touches no disk. For a command-line tool, <code>argparse</code> turns <code>--limit 5</code> into <code>args.limit</code>; a real program calls <code>parser.parse_args()</code> with no list so it reads what the user typed.",
   'import os, argparse\nfrom pathlib import PurePosixPath\n\nos.environ["SHIPCODE_MODE"] = "demo"    # normally set by the shell, not in code\nmode = os.environ.get("SHIPCODE_MODE", "dev")\nport = int(os.environ.get("SHIPCODE_PORT", "8000"))   # a string until converted\nprint(mode, port)\ntry:\n    key = os.environ["SHIPCODE_API_KEY_DEMO"]\nexcept KeyError:\n    print("required setting is missing")\n\np = PurePosixPath("data") / "raw" / "sales_2024.csv"\nprint(p)\nprint(p.name, p.stem, p.suffix, p.parent)\n\nparser = argparse.ArgumentParser(description="Clean a CSV")\nparser.add_argument("path")\nparser.add_argument("--limit", type=int, default=100)\nparser.add_argument("--dry-run", action="store_true")\nargs = parser.parse_args(["data/sales.csv", "--limit", "5"])\nprint(args.path, args.limit, args.dry_run)', run=True,
   q=Q("What does this show?", 'import argparse\n\nparser = argparse.ArgumentParser()\nparser.add_argument("--limit", type=int, default=100)\nargs = parser.parse_args(["--limit", "7"])\nprint(args.limit * 2)', ["14", "77", "100"],
       "type=int converts the text \"7\" to the number 7 before you get it, so 7 * 2 is 14. Without type=int it would be the text \"7\" and the result would be 77.")),
 Sd("Project shape: virtual environments, pyproject.toml, layout",
    "A <b>virtual environment</b> is a private folder of installed packages for one project, so project A can use pandas 1 and project B pandas 2 without fighting. <b>pyproject.toml</b> is the one file that describes the project: its name, Python version, dependencies and tool settings. A common layout puts the code in a package folder, tests beside it, and keeps input/output (reading files, printing, argparse) in a thin <code>cli.py</code> while the real logic sits in small functions that are easy to test. Habits that make code readable: functions that do <b>one thing</b>, names that say what a value <b>is</b> (<code>total_paid_amount</code>, not <code>d</code>), a short <b>docstring</b> (the first string in a function) saying what it does, and no secrets in the repository (<code>.venv/</code> and <code>.env</code> go in <code>.gitignore</code>). Exact commands differ a little by operating system, so check your tool's docs.",
    '# --- terminal (display only) ---\n#   python -m venv .venv\n#   source .venv/bin/activate        # Windows: .venv\\Scripts\\activate\n#   pip install -e ".[dev]"          # install this project plus the dev extras\n\n# --- layout ---\n# orders-tool/\n#   pyproject.toml\n#   README.md\n#   .gitignore                       # .venv/  .env\n#   src/orders_tool/\n#       __init__.py\n#       cli.py                       # argparse + print: thin\n#       config.py                    # reads environment variables\n#       models.py                    # dataclasses and enums\n#       errors.py                    # custom exceptions\n#       service.py                   # the logic: no print, no input()\n#   tests/\n#       test_service.py\n\n# --- pyproject.toml ---\n# [build-system]\n# requires = ["setuptools>=61"]\n# build-backend = "setuptools.build_meta"\n#\n# [project]\n# name = "orders-tool"\n# version = "0.1.0"\n# requires-python = ">=3.10"\n# dependencies = ["requests>=2.31"]\n#\n# [project.optional-dependencies]\n# dev = ["pytest"]\n#\n# [tool.pytest.ini_options]\n# testpaths = ["tests"]\n\n# --- a small, well-named function with a docstring ---\ndef total_paid_amount(orders: list[dict]) -> float:\n    """Return the sum of amounts of orders whose status is \'paid\'."""\n    return sum(o["amount"] for o in orders if o["status"] == "paid")',
    q=QC("Which function name best follows the habits on this screen?", ["<code>def total_paid_amount(orders):</code>", "<code>def proc(d):</code>", "<code>def doStuff(x):</code>"], 0,
         "A good name says what the function returns and what it works on. Short mystery names force every reader to open the body to learn what it does.")),
 S("Final task: load config from the environment",
   "Real programs start by reading settings. You will write that step as a <b>pure function</b>: it takes a dict (the environment, passed in rather than read from <code>os.environ</code>) and returns a clean settings dict. Passing the dict in makes it trivial to test, which is the point of this module. <code>.lower()</code> makes text lower case and <code>x in (\"1\", \"true\", \"yes\")</code> checks membership in a small tuple.",
   q=W("Write <code>load_config(env)</code> where <code>env</code> is a dict of strings. Return a dict with keys: <code>mode</code> (from <code>APP_MODE</code>, default <code>'dev'</code>), <code>port</code> (from <code>APP_PORT</code> as an int, default <code>8000</code>; raise <code>ValueError</code> if it is not a whole number or not between 1 and 65535), <code>debug</code> (True when <code>APP_DEBUG</code> is <code>1</code>, <code>true</code> or <code>yes</code> in any capitals; default False) and <code>api_key</code> (from <code>API_KEY</code>; raise <code>ValueError</code> if it is missing or an empty string).",
       "def load_config(env):\n    return {}\n",
       "def load_config(env):\n    api_key = env.get(\"API_KEY\", \"\")\n    if not api_key:\n        raise ValueError(\"API_KEY is required\")\n    port = int(env.get(\"APP_PORT\", \"8000\"))\n    if not 1 <= port <= 65535:\n        raise ValueError(\"APP_PORT out of range\")\n    return {\n        \"mode\": env.get(\"APP_MODE\", \"dev\"),\n        \"port\": port,\n        \"debug\": env.get(\"APP_DEBUG\", \"\").lower() in (\"1\", \"true\", \"yes\"),\n        \"api_key\": api_key,\n    }\n",
       exprs=[("defaults", "load_config({'API_KEY': 'k'})"),
              ("everything set", "load_config({'API_KEY': 'k2', 'APP_MODE': 'prod', 'APP_PORT': '9090', 'APP_DEBUG': 'yes'})"),
              ("debug is case-insensitive", "load_config({'API_KEY': 'k', 'APP_DEBUG': 'TRUE'})['debug']"),
              ("debug 0 is False", "load_config({'API_KEY': 'k', 'APP_DEBUG': '0'})['debug']"),
              ("port is an int", "type(load_config({'API_KEY': 'k', 'APP_PORT': '81'})['port']) is int"),
              ("missing key raises ValueError", "_raises(lambda: load_config({}), ValueError)"),
              ("empty key raises ValueError", "_raises(lambda: load_config({'API_KEY': ''}), ValueError)"),
              ("port not a number raises ValueError", "_raises(lambda: load_config({'API_KEY': 'k', 'APP_PORT': 'abc'}), ValueError)"),
              ("port 0 raises ValueError", "_raises(lambda: load_config({'API_KEY': 'k', 'APP_PORT': '0'}), ValueError)"),
              ("port 65536 raises ValueError", "_raises(lambda: load_config({'API_KEY': 'k', 'APP_PORT': '65536'}), ValueError)"),
              ("port 65535 is fine", "load_config({'API_KEY': 'k', 'APP_PORT': '65535'})['port']")],
       hint="int('abc') already raises ValueError. After converting, check 1 <= port <= 65535. For debug: env.get('APP_DEBUG', '').lower() in ('1', 'true', 'yes').",
       prelude=_RZ)),
 ])

# =====================================================================================================
# 3. CONCURRENCY
# =====================================================================================================
_AS_NOTE = " (asyncio needs a real event loop, which this page cannot start, so this screen is for reading: copy it to a file on your computer and run it. The output shown was produced by actually running it.)"

_ASYNC_CALL = ('import asyncio\n\nasync def fetch_user(user_id):\n    await asyncio.sleep(0.1)       # stands in for a slow API call\n'
               '    return {"id": user_id, "name": f"user{user_id}"}\n\nasync def main():\n    coro = fetch_user(1)\n    print(type(coro).__name__)     # nothing has run yet\n'
               '    user = await coro\n    print(user)\n\nasyncio.run(main())')
_ASYNC_GATHER = ('import asyncio, time\n\nasync def call(name, delay):\n    await asyncio.sleep(delay)\n    print("finished", name)\n    return name.upper()\n\n'
                 'async def main():\n    start = time.perf_counter()\n    results = await asyncio.gather(call("a", 0.3), call("b", 0.1), call("c", 0.2))\n'
                 '    print(results)\n    print("overlapped:", time.perf_counter() - start < 0.5)   # one after another would take 0.6\n\nasyncio.run(main())')
_ASYNC_SEM = ('import asyncio\n\nrunning = 0\npeak = 0\n\nasync def call(i, sem):\n    global running, peak\n    async with sem:            # at most 3 tasks can be inside this block\n'
              '        running += 1\n        peak = max(peak, running)\n        await asyncio.sleep(0.05)\n        running -= 1\n    return i\n\n'
              'async def main():\n    sem = asyncio.Semaphore(3)\n    results = await asyncio.gather(*(call(i, sem) for i in range(10)))\n    print(results)\n    print("most at once:", peak)\n\nasyncio.run(main())')
_ASYNC_TIMEOUT = ('import asyncio\n\nasync def slow_call():\n    await asyncio.sleep(1)\n    return "done"\n\nasync def fine():\n    return "fine"\n\nasync def broken():\n    raise ValueError("boom")\n\n'
                  'async def main():\n    try:\n        await asyncio.wait_for(slow_call(), timeout=0.1)\n    except asyncio.TimeoutError:\n        print("gave up after 0.1 seconds")\n\n'
                  '    results = await asyncio.gather(fine(), broken(), return_exceptions=True)\n    print(results)\n\nasyncio.run(main())')

PM("py-async", "Python Pro", "Concurrency: threads, processes and asyncio",
   "Calling many APIs, files or models one after another is the most common reason a data or AI pipeline is slow; knowing how to overlap the waiting, safely, is a core engineering skill.",
 [
 S("CPU-bound or I/O-bound?",
   "Before choosing a tool, ask what your program spends its time on. <b>I/O-bound</b> (input/output): it mostly <b>waits</b> for something outside the CPU, such as a web API, a database or a disk. <b>CPU-bound</b>: it mostly <b>computes</b>, such as parsing, maths or training. Waiting jobs can be <b>overlapped</b>: start all the requests, then collect answers, so total time is about the slowest one. Computing jobs cannot be overlapped on one CPU core: you need more cores. The model below uses invented seconds to show the difference.",
   'waits = [2, 2, 2]          # three API calls, each waits 2 seconds for the server\nprint("one after another:", sum(waits), "seconds")\nprint("waiting together: ", max(waits), "seconds")\n\ncpu = [2, 2, 2]            # three jobs, each needs 2 seconds of computing\ncores = 1\nprint("on one core:      ", sum(cpu), "seconds")\nprint("on three cores:   ", max(cpu), "seconds (needs three cores)")', run=True,
   q=QC("A script downloads 50 pages one at a time and almost all its time is spent waiting for the servers. What helps most?", ["Overlap the waits with threads or asyncio", "Use 50 separate processes to use more CPU", "Buy a faster CPU"], 0,
        "The CPU is idle while waiting, so a faster CPU or more cores change little. Overlapping the waits lets all 50 requests be in flight at once.")),
 Sd("Threads, processes and asyncio in plain words",
    "<b>Thread</b>: another worker inside the same program, sharing its memory. <b>Process</b>: a separate copy of the program with its own memory and its own Python, so it can run on another core, but sending data between processes costs time. <b>asyncio</b>: one thread that switches between tasks whenever one says \"I am waiting\"; it is cheap, so it can handle thousands of waiting tasks. About the <b>GIL</b> (Global Interpreter Lock): in standard CPython, only one thread runs Python bytecode at a time. A thread that is waiting on I/O lets go of the lock, so threads still help I/O-bound work but not pure-Python CPU work. (Newer Python versions have an experimental build without the GIL; check the documentation for your version.) Rule of thumb: I/O-bound, few to hundreds of tasks, simple code: threads. I/O-bound with very many tasks: asyncio. CPU-bound: processes.",
    'from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor\n\ndef fetch(url):                 # I/O-bound: mostly waits on the network\n    ...\n\nwith ThreadPoolExecutor(max_workers=8) as pool:\n    pages = list(pool.map(fetch, urls))      # results come back in the order of urls\n\ndef crunch(n):                  # CPU-bound: pure computing\n    return sum(i * i for i in range(n))\n\nif __name__ == "__main__":      # required for processes on some systems\n    with ProcessPoolExecutor() as pool:\n        totals = list(pool.map(crunch, [10**6] * 4))',
    q=QC("Which tool can speed up a <b>CPU-bound</b>, pure-Python job on a multi-core machine?", ["Several processes", "Several threads", "asyncio"], 0,
         "Each process has its own interpreter and its own GIL, so they truly run in parallel. Threads share one GIL, and asyncio is a single thread.")),
 Sd("async def and await",
    "An <code>async def</code> function is a <b>coroutine function</b>. Calling it does <b>not</b> run it: it returns a coroutine object, a paused job. <code>await</code> means \"run this job, and while it waits let other tasks run\". <code>asyncio.run(main())</code> starts the <b>event loop</b>, the scheduler that switches between tasks, and runs <code>main</code> to the end. If you forget <code>await</code>, you get the coroutine object and a warning that it was never awaited. Here <code>asyncio.sleep</code> stands in for a slow API call." + _AS_NOTE,
    _with_out(_ASYNC_CALL),
    q=QC("Inside <code>async def main()</code>, you write <code>user = fetch_user(1)</code> (no await). What is <code>user</code>?", ["A coroutine object: the call has not run yet", "The dict that fetch_user returns", "None"], 0,
         "Calling an async function only creates the paused job. You must await it (or schedule it) to get the result.")),
 Sd("Run many at once: asyncio.gather",
    "<code>asyncio.gather(a, b, c)</code> starts several coroutines together and waits for all of them. It returns their results <b>in the order you passed them</b>, not in the order they finished. Total time is about the slowest one. A warning: the whole point is that tasks hand control back at each <code>await</code>. A blocking call such as <code>time.sleep(1)</code> or a slow <code>requests.get</code> inside an async function freezes <b>every</b> task, so use async-friendly libraries or <code>await asyncio.sleep</code>." + _AS_NOTE,
    _with_out(_ASYNC_GATHER),
    q=QC("In the example, c finished before a. What order does <code>results</code> have?", ["Argument order: A, B, C", "Finish order: B, C, A", "Random order"], 0,
         "gather keeps argument order for its results, whatever the finishing order. Notice the printed \"finished\" lines are in finish order (b, c, a) while the list is A, B, C.")),
 Sd("Limit how many run at once: Semaphore",
    "If you fire 1,000 requests at once, the server may block you (rate limit) or you may run out of connections. A <b>semaphore</b> is a counter of permits: <code>asyncio.Semaphore(3)</code> lets three tasks into the <code>async with sem:</code> block at a time; the others wait their turn. The example counts how many are inside the block at once and reports the peak." + _AS_NOTE,
    _with_out(_ASYNC_SEM),
    q=QC("You create <code>asyncio.Semaphore(5)</code> and start 100 tasks that all use <code>async with sem</code>. How many are inside the block at the same moment, at most?", ["5", "100", "1"], 0,
         "The number is the count of permits. Five tasks hold a permit; the other 95 wait until one is released.")),
 Sd("Timeouts and failures",
    "A call that never returns will hang your whole pipeline, so always put a limit. <code>asyncio.wait_for(coro, timeout=seconds)</code> cancels the call and raises <code>asyncio.TimeoutError</code> if it takes too long. (On Python 3.11 and newer that is the same class as the built-in <code>TimeoutError</code>; <code>async with asyncio.timeout(seconds):</code> is another way on 3.11 and newer.) By default, if one task in a <code>gather</code> raises, the error comes out of <code>gather</code> straight away. With <code>return_exceptions=True</code>, errors are returned as items in the result list so one failure does not hide the others." + _AS_NOTE,
    _with_out(_ASYNC_TIMEOUT),
    q=QC("What does <code>return_exceptions=True</code> change in <code>asyncio.gather</code>?", ["Failed tasks appear as exception objects in the results list instead of raising", "It retries failed tasks automatically", "It ignores failures and leaves them out of the list"], 0,
         "Every task gets a slot in the list: either its value or the exception object. You then check each item yourself. There is no automatic retry.")),
 S("Retries: exponential backoff and jitter",
   "APIs fail for short moments (busy server, network blip). A <b>retry</b> tries again, but not instantly: waiting longer after each failure gives the server room to recover. <b>Exponential backoff</b> doubles the wait each time: 1, 2, 4, 8 seconds, with a <b>cap</b> so it never grows forever. <b>Jitter</b> adds randomness to the wait: if 1,000 clients all fail together and all retry after exactly 4 seconds, they all hit the server together again. One common choice, \"full jitter\", waits a random time between 0 and the computed delay. Below the random source is passed in as <code>rand</code>, so we can test with fixed numbers. In real code pass <code>random.random</code>.",
   'def backoff_delay(attempt, base=1.0, cap=30.0):\n    """Wait before retry number `attempt` (0, 1, 2, ...)."""\n    return min(cap, base * 2 ** attempt)\n\nprint([backoff_delay(a) for a in range(8)])\n\ndef with_jitter(delay, rand):\n    """Full jitter: somewhere between 0 and the delay. rand() returns 0 <= x < 1."""\n    return delay * rand()\n\nprint(with_jitter(8.0, lambda: 0.5))\nprint(with_jitter(8.0, lambda: 0.99))', run=True,
   q=Q("What does this show?", 'def backoff_delay(attempt, base=1.0, cap=30.0):\n    return min(cap, base * 2 ** attempt)\n\nprint(backoff_delay(3, base=0.5, cap=10))', ["4.0", "1.5", "8.0"],
       "2 ** 3 is 8, times the base 0.5 is 4.0, which is under the cap of 10. If the cap were 3 the answer would be 3.")),
 S("The retry loop, written by hand",
   "Now put the delays into a loop. Rules that matter in real systems: retry only <b>transient</b> errors (timeouts, connection errors, server-busy), never errors that will fail again (bad input, 401 not allowed, 404 not found); after the <b>last</b> try, let the error out instead of swallowing it; and only retry operations that are safe to repeat (a retried \"charge the card\" may charge twice unless it is idempotent). The sleep function is passed in so this test run does not really wait; in production pass <code>time.sleep</code> (or <code>await asyncio.sleep</code> in an async version).",
   'def retry(fn, tries, base, sleep):\n    for attempt in range(tries):\n        try:\n            return fn()\n        except ConnectionError:\n            if attempt == tries - 1:\n                raise                       # out of tries: let the error out\n            sleep(base * 2 ** attempt)\n\ncalls = []\ndef flaky():\n    calls.append(1)\n    if len(calls) < 3:\n        raise ConnectionError("server busy")\n    return "ok"\n\nwaited = []\nprint(retry(flaky, tries=5, base=1.0, sleep=waited.append))\nprint(len(calls), waited)', run=True,
   q=QE("What happens here?", 'def retry(fn, tries, base, sleep):\n    for attempt in range(tries):\n        try:\n            return fn()\n        except ConnectionError:\n            if attempt == tries - 1:\n                raise\n            sleep(base * 2 ** attempt)\n\ndef always_down():\n    raise ConnectionError("down")\n\nretry(always_down, tries=2, base=1.0, sleep=lambda s: None)',
        "ConnectionError", ["It returns None quietly", "A ConnectionError comes out after the second try", "An infinite loop"], 1,
        "Try 1 fails and waits; try 2 fails and, being the last, re-raises. The caller needs to know the call really failed.")),
 S("Final task: a retry helper",
   "Extend the loop you just read. The new rules: only exceptions listed in <code>retry_on</code> are retried (anything else is raised <b>at once</b>, without sleeping), and the delay is capped. It is a pure-Python version of what libraries do for you, and it is the kind of helper interviewers ask you to write on a whiteboard.",
   q=W("Write <code>retry_call(fn, tries, base, cap, retry_on, sleep)</code>. Call <code>fn()</code> up to <code>tries</code> times and return its result on the first success. If it raises an exception that is an instance of <code>retry_on</code> (a tuple of classes) and tries remain, call <code>sleep(delay)</code> with <code>delay = min(cap, base * 2 ** k)</code> where <code>k</code> is 0 for the first wait, then try again. After the last failed try, raise that exception without sleeping. An exception not in <code>retry_on</code> is raised immediately.",
       "def retry_call(fn, tries, base, cap, retry_on, sleep):\n    return fn()\n",
       "def retry_call(fn, tries, base, cap, retry_on, sleep):\n    for k in range(tries):\n        try:\n            return fn()\n        except retry_on:\n            if k == tries - 1:\n                raise\n            sleep(min(cap, base * 2 ** k))\n",
       exprs=[("works first time, no sleeping", "trial(0, 3)"),
              ("fails twice then works", "trial(2, 5)"),
              ("gives up after the last try", "trial(9, 3)"),
              ("delays are capped", "trial(9, 6, base=1.0, cap=4.0)"),
              ("an error not in retry_on is raised at once", "trial(5, 5, exc=ValueError)"),
              ("TimeoutError is also retried", "trial(1, 3, exc=TimeoutError)"),
              ("a single try never sleeps", "trial(1, 1)")],
       hint="Loop k over range(tries). try: return fn(). except retry_on: if k is the last index, raise; else sleep(min(cap, base * 2 ** k)).",
       prelude="def make_flaky(fail_times, exc=ConnectionError):\n    state = {'calls': 0}\n    def fn():\n        state['calls'] += 1\n        if state['calls'] <= fail_times:\n            raise exc('fail %d' % state['calls'])\n        return 'ok'\n    fn.state = state\n    return fn\n\ndef trial(fail_times, tries, base=1.0, cap=30.0, exc=ConnectionError):\n    fn = make_flaky(fail_times, exc)\n    sleeps = []\n    try:\n        res = retry_call(fn, tries, base, cap, (ConnectionError, TimeoutError), sleeps.append)\n    except Exception as e:\n        res = type(e).__name__\n    return (res, fn.state['calls'], sleeps)\n")),
 ])

# =====================================================================================================
# 4. PERFORMANCE AND MEMORY
# =====================================================================================================
PM("py-perf", "Python Pro", "Performance and memory",
   "Slow or memory-hungry code is the usual reason a pipeline fails at real data size; these tools let you find the cost and choose the cheaper approach.",
 [
 S("Measure first",
   "Do not guess what is slow: <b>measure</b>. <code>time.perf_counter()</code> returns a high-resolution clock reading in seconds; the difference between two readings is how long the code between them took. The number changes every run (other programs, the machine's mood), so never print it in a test and compare for equality; look at its size, and repeat. For tiny snippets, <code>timeit.timeit(\"sum(range(100))\", number=10000)</code> repeats for you. To see <b>which function</b> in a big program eats the time, use a profiler from the terminal: <pre>python -m cProfile -s cumtime my_script.py</pre> It lists each function with <code>ncalls</code> (how many calls), <code>tottime</code> (time in the function itself) and <code>cumtime</code> (including what it calls). Fix the biggest line, then measure again.",
   'import time\n\ndef slow_sum(n):\n    total = 0\n    for i in range(n):\n        total += i\n    return total\n\nstart = time.perf_counter()\nanswer = slow_sum(20000)\nelapsed = time.perf_counter() - start\nprint(answer)\nprint("took a positive amount of time:", elapsed > 0)\n# elapsed itself differs on every run, so we do not print it', run=True,
   q=QC("Your script takes 30 seconds. What is the best first step?", ["Profile or time it to find where the time goes", "Rewrite everything with threads", "Switch every list to a set"], 0,
        "Without a measurement you may spend a day speeding up a part that takes 1 percent of the time. Measure, fix the biggest cost, measure again.")),
 S("Complexity with real counts",
   "<b>Complexity</b> describes how the work grows as the input size n grows. A dict or set lookup is about the same work however big (<b>O(1)</b>). A loop over the data is <b>O(n)</b>. Sorting is <b>O(n log n)</b>. A loop inside a loop over the same data is <b>O(n squared)</b>: ten times the data means a hundred times the work. Below we count the comparisons made by two ways of asking \"is there a duplicate?\". Counting steps is deterministic, which timing is not.",
   'def has_dup_slow(items):\n    checks = 0\n    for i in range(len(items)):\n        for j in range(i + 1, len(items)):\n            checks += 1\n            if items[i] == items[j]:\n                return True, checks\n    return False, checks\n\ndef has_dup_fast(items):\n    seen = set()\n    checks = 0\n    for x in items:\n        checks += 1\n        if x in seen:\n            return True, checks\n        seen.add(x)\n    return False, checks\n\nfor n in (10, 100, 200):\n    data = list(range(n))        # no duplicates: worst case\n    print(n, has_dup_slow(data)[1], has_dup_fast(data)[1])', run=True,
   q=Q("What does this show?", 'def pairs(n):\n    checks = 0\n    for i in range(n):\n        for j in range(i + 1, n):\n            checks += 1\n    return checks\n\nprint(pairs(20))', ["190", "20", "400"],
       "Every pair is looked at once: 20 * 19 / 2 = 190. Doubling n roughly quadruples this number, which is what O(n squared) means.")),
 S("list, set, dict or deque?",
   "Choose the container for the question you ask most. <code>x in a_list</code> scans item by item: <b>O(n)</b>. <code>x in a_set</code> and <code>key in a_dict</code> use a <b>hash</b> (a number computed from the value that says where to look): about <b>O(1)</b>. A dict also stores a value per key. Taking from the front of a list (<code>pop(0)</code>, <code>insert(0, x)</code>) shifts every item, <b>O(n)</b>; a <code>deque</code> (double-ended queue, from <code>collections</code>) does it in O(1) at either end. Sets and dict keys must be <b>hashable</b> (numbers, strings, tuples; not lists).",
   'from collections import deque\n\nnames = ["asha", "ravi", "meera", "kiran"]\nprint("meera" in names)            # list: scans, O(n)\nname_set = set(names)\nprint("meera" in name_set)         # set: hash lookup, about O(1)\n\nages = {"asha": 30, "ravi": 25}\nprint(ages["ravi"])\nprint(ages.get("zed", "unknown"))\n\nq = deque([1, 2, 3])\nq.append(4)\nq.appendleft(0)                    # O(1); list.insert(0, x) is O(n)\nprint(q.popleft())                 # O(1); list.pop(0) is O(n)\nprint(list(q))', run=True,
   q=QC("You must check, 1 million times, whether an id is among 100,000 known ids. Which structure?", ["A set of the ids", "A list of the ids", "A deque of the ids"], 0,
        "A set answers each check in about constant time. A list would scan up to 100,000 items per check: up to 100 billion comparisons in total.")),
 S("Generators: produce one value at a time",
   "A <b>generator</b> is a function with <code>yield</code> instead of <code>return</code>. It does not build all results; it hands out one value each time you ask (with <code>next()</code> or a <code>for</code> loop), then pauses where it was. That makes it <b>lazy</b>: values are made only when needed, and the memory used stays small no matter how many there will be. Two things to remember: a generator is <b>used up</b> after one pass, and a generator expression <code>(x for x in ...)</code> with round brackets is the short form. <code>sys.getsizeof</code> shows the size of the container object itself (not the items inside).",
   'import sys\n\ndef squares(n):\n    for i in range(n):\n        yield i * i\n\ngen = squares(5)\nprint(next(gen))\nprint(next(gen))\nprint(list(gen))       # takes the rest\nprint(list(gen))       # nothing left: used up\n\nbig_list = [i * i for i in range(10000)]\nbig_gen = (i * i for i in range(10000))\nprint(sys.getsizeof(big_list) > sys.getsizeof(big_gen))\nprint(sum(big_gen))', run=True,
   q=Q("What does this show?", 'def squares(n):\n    for i in range(n):\n        yield i * i\n\ngen = squares(3)\nprint(list(gen))\nprint(sum(gen))', ["[0, 1, 4]\n0", "[0, 1, 4]\n5", "[0, 1, 4]\n[0, 1, 4]"],
       "list(gen) consumed everything. The second pass finds nothing left, so sum of nothing is 0. If you need two passes, make the generator again or store a list.")),
 S("Streaming big files: one line or one chunk at a time",
   "If a file is bigger than memory, <code>f.read()</code> or <code>f.readlines()</code> will crash. A file object is itself lazy: <code>for line in f:</code> reads one line at a time. Chain generators into a <b>pipeline</b>: each stage pulls one item from the previous stage, so only one line is in memory at once. For binary or very long lines, <code>f.read(size)</code> returns up to <code>size</code> characters and an empty string at the end. In pandas, <code>pd.read_csv(path, chunksize=100_000)</code> returns an iterator of DataFrames, one per chunk. Here <code>io.StringIO</code> acts like an open file so the example runs anywhere; with a real file you write <code>with open(path) as f:</code>.",
   'import io\n\ntext = "id,amount\\n1,10\\n2,20\\n3,30\\n4,40\\n5,50\\n"\nf = io.StringIO(text)          # behaves like an open file\n\ndef amounts(lines):\n    next(lines)                # skip the header line\n    for line in lines:\n        yield int(line.split(",")[1])\n\nprint(sum(amounts(f)))         # one line in memory at a time\n\nf = io.StringIO(text)\nwhile True:\n    chunk = f.read(10)         # up to 10 characters\n    if not chunk:\n        break\n    print(repr(chunk))', run=True,
   q=QC("A 20 GB log file must be scanned for lines containing ERROR on a laptop with 8 GB of memory. Which approach works?", ["<code>for line in f:</code> and test each line", "<code>lines = f.readlines()</code> then loop", "<code>text = f.read()</code> then <code>.split(\"\\n\")</code>"], 0,
        "Only the first approach keeps one line in memory at a time. The other two try to load all 20 GB.")),
 S("itertools: ready-made lazy building blocks",
   "The <code>itertools</code> module has fast, lazy tools for looping. <code>islice(it, n)</code> takes the first n items of any iterator, even an endless one (<code>count(10)</code> counts 10, 11, 12, ... forever). <code>chain(a, b)</code> loops over several things as one. <code>accumulate</code> gives running totals. <code>combinations(items, r)</code> and <code>product</code> make groups. <code>groupby(items, key)</code> groups <b>neighbouring</b> items with the same key: sort first if equal keys are not already next to each other.",
   'import itertools\n\nprint(list(itertools.islice(itertools.count(10), 3)))\nprint(list(itertools.chain([1, 2], [3], [4, 5])))\nprint(list(itertools.accumulate([1, 2, 3, 4])))\nprint(list(itertools.combinations("abc", 2)))\nprint(list(itertools.product([0, 1], repeat=2)))\n\nrows = [("A", 1), ("A", 2), ("B", 5), ("B", 1)]\nfor key, group in itertools.groupby(rows, key=lambda r: r[0]):\n    print(key, [v for _, v in group])', run=True,
   q=Q("What does this show?", 'import itertools\n\nprint([k for k, _ in itertools.groupby("AABA")])', ["['A', 'B', 'A']", "['A', 'B']", "['A', 'A', 'B', 'A']"],
       "groupby only merges neighbours: AA, then B, then A again. For one group per key, sort the data first.")),
 S("Do not repeat work: cache and hoist",
   "Many slow programs compute the same thing again and again. Two fixes. <b>Cache</b> (remember) results: <code>@lru_cache</code> from <code>functools</code> stores the answer for each set of arguments (which must be hashable), so a repeated call is a lookup. <code>cache_info()</code> reports <code>hits</code> (answered from memory) and <code>misses</code> (really computed). <code>functools.cache</code> is the same with no size limit. <b>Hoist</b> work out of a loop: build a lookup dict, compile a regex, or compute <code>len(x)</code> once <b>before</b> the loop instead of inside it. Below, the plain recursive Fibonacci recomputes the same values thousands of times.",
   'from functools import lru_cache\n\ncalls = 0\ndef fib_slow(n):\n    global calls\n    calls += 1\n    return n if n < 2 else fib_slow(n - 1) + fib_slow(n - 2)\n\nprint(fib_slow(15), calls)\n\n@lru_cache(maxsize=None)\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\n\nprint(fib(30))\nprint(fib.cache_info())', run=True,
   q=Q("What does this show?", 'from functools import lru_cache\n\n@lru_cache(maxsize=None)\ndef f(x):\n    return x * 2\n\nf(2)\nf(2)\nf(3)\ninfo = f.cache_info()\nprint(info.hits, info.misses)', ["1 2", "2 1", "0 3"],
       "f(2) the first time is a miss, f(2) again is a hit, f(3) is a miss: one hit, two misses.")),
 S("Small wins: join, comprehensions, generator expressions",
   "Building a long string with <code>s += piece</code> in a loop can make a new string every time (CPython sometimes optimises this, but you should not rely on it); <code>\"\".join(pieces)</code> builds it once and is the safe, linear way. <code>join</code> needs strings, so convert numbers first. A <b>list comprehension</b> is usually a bit faster than appending in a loop and shorter; measure if it matters. If you only need to loop once (<code>sum</code>, <code>any</code>, <code>max</code>), pass a generator expression so no list is built, and <code>any</code> stops at the first match.",
   'words = ["data", "is", "the", "new", "oil"]\n\ns = ""\nfor w in words:\n    s += w + " "\nprint(s.strip())\nprint(" ".join(words))\n\nsquares = []\nfor n in range(5):\n    squares.append(n * n)\nprint(squares == [n * n for n in range(5)])\n\nprint(sum(n * n for n in range(5)))\nprint(any(w == "oil" for w in words))\nprint({w: len(w) for w in words})', run=True,
   q=QE("What happens here?", 'print(",".join([1, 2, 3]))', "TypeError", ["It prints 1,2,3", "A TypeError: join needs strings", "It prints 6"], 1,
        "join only accepts strings. Convert first: \",\".join(str(n) for n in [1, 2, 3]).")),
 S("Final task: batches, lazily",
   "Sending 1 million rows to a database or an API one at a time is slow; sending them all at once may be too big. The standard answer is to send <b>batches</b>. You will write a generator that cuts any iterable, even an endless stream, into lists of at most <code>size</code> items. Because it is a generator it must not read ahead: grading includes an endless stream and takes only the first batches. (The grader stops code that runs too many steps, so building the whole list first will fail.)",
   q=W("Write the generator function <code>batches(iterable, size)</code> (use <code>yield</code>). It yields lists of exactly <code>size</code> items in order; the last list may be shorter. An empty input yields nothing. If <code>size</code> is less than 1, raise <code>ValueError</code>.",
       "def batches(iterable, size):\n    return [list(iterable)]\n",
       "def batches(iterable, size):\n    if size < 1:\n        raise ValueError(\"size must be at least 1\")\n    batch = []\n    for item in iterable:\n        batch.append(item)\n        if len(batch) == size:\n            yield batch\n            batch = []\n    if batch:\n        yield batch\n",
       exprs=[("even split", "list(batches([1, 2, 3, 4], 2))"),
              ("short last batch", "list(batches(range(7), 3))"),
              ("empty input", "list(batches([], 3))"),
              ("size 1", "list(batches('abc', 1))"),
              ("size bigger than the input", "list(batches([1, 2], 10))"),
              ("is lazy: first batch of an endless stream", "next(batches(naturals(), 3))"),
              ("is lazy: three batches of an endless stream", "list(islice(batches(naturals(), 2), 3))"),
              ("size 0 raises ValueError", "_raises(lambda: list(batches([1], 0)), ValueError)")],
       hint="Keep a list called batch. Append each item; when len(batch) == size, yield it and start a new list. After the loop, yield what is left if it is not empty.",
       prelude=_RZ + "from itertools import islice\n\ndef naturals():\n    n = 0\n    while True:\n        yield n\n        n += 1\n")),
 ])

# =====================================================================================================
# 5. STATISTICS AND EXPERIMENTS
# =====================================================================================================
PM("py-ds-stats", "Python Pro", "Statistics and experiments",
   "Data science interviews test whether you can reason about numbers: summaries, samples, A/B tests and the traps that make confident conclusions wrong.",
 [
 S("Centre and spread: mean, median, variance, standard deviation",
   "The <b>mean</b> is the sum divided by the count. The <b>median</b> is the middle value once sorted (the average of the two middle ones if the count is even); one extreme value drags the mean but barely moves the median. <b>Variance</b> measures spread: average the squared distances from the mean. <b>Standard deviation</b> (std) is its square root, back in the original units. There are two versions: divide by <b>n</b> when your data is the whole population; divide by <b>n - 1</b> when it is a sample used to estimate a larger population. In pandas, <code>.std()</code> and <code>.var()</code> divide by n - 1 by default; NumPy's <code>np.std</code> divides by n by default (it has a <code>ddof</code> argument to change it). Know which one you are calling.",
   'import statistics as st\n\npay = [2, 4, 4, 4, 5, 5, 7, 9]\nn = len(pay)\nmean = sum(pay) / n\nprint("mean:", mean)\nprint("median:", st.median(pay))\nsquared = [(x - mean) ** 2 for x in pay]\nprint("sum of squared distances:", sum(squared))\nprint("variance, divide by n:", sum(squared) / n)\nprint("variance, divide by n-1:", round(sum(squared) / (n - 1), 4))\nprint("std, population:", st.pstdev(pay))\nprint("std, sample:", round(st.stdev(pay), 4))', run=True,
   q=Q("What does this show?", 'import statistics as st\n\nx = [1, 2, 3, 10]\nprint(st.mean(x), st.median(x))', ["4 2.5", "4 2", "2.5 4"],
       "The mean is 16 / 4 = 4. The median is the average of the two middle values 2 and 3, which is 2.5. The outlier 10 pulls the mean above the median.")),
 Sh("Percentiles and outliers",
    "The <b>p-th percentile</b> is the value below which p percent of the data falls: the median is the 50th. With sorted data, position <code>(n - 1) * p / 100</code> is usually between two items, so we blend them (<b>linear interpolation</b>); this is pandas' default for <code>.quantile()</code>. The <b>IQR</b> (interquartile range) is the 75th minus the 25th percentile; a common rule flags values above <code>Q3 + 1.5 * IQR</code> as outliers. Always look at what an outlier is (an error? a real big customer?) before removing it.",
    'import pandas as pd\n\ndef percentile(xs, p):               # p between 0 and 100\n    xs = sorted(xs)\n    pos = (len(xs) - 1) * p / 100\n    lo = int(pos)\n    hi = min(lo + 1, len(xs) - 1)\n    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)\n\nsalary = pd.Series([30, 32, 35, 36, 40, 42, 45, 300])\nprint(salary.mean(), salary.median())\nprint(salary.quantile([0.25, 0.5, 0.75]).tolist())\nprint(percentile(list(salary), 25))\nq1, q3 = salary.quantile(0.25), salary.quantile(0.75)\nfence = q3 + 1.5 * (q3 - q1)\nprint("fence:", fence)\nprint(salary[salary > fence].tolist())', run=True,
    q=Qh("What does this show?", "import pandas as pd\ns = pd.Series([1, 2, 3, 4, 100])\nprint(s.median(), s.mean())", ["3.0 22.0", "3.0 3.0", "22.0 3.0"],
         "The middle value is 3. The mean (1 + 2 + 3 + 4 + 100) / 5 is 22. A single outlier made the mean a poor description of a typical value.")),
 S("Correlation: how two things move together",
   "<b>Correlation</b> (Pearson's r) is a number from -1 to +1: +1 means they rise together in a perfect straight line, -1 means one rises as the other falls, near 0 means no <b>straight-line</b> relationship. It is the covariance (do the two deviate from their means in the same direction?) divided by both spreads. Two cautions: r only sees straight lines (a perfect U-shape has r = 0), and <b>correlation is not causation</b>: ice-cream sales and sunburns rise together because of a third thing, summer. In pandas, <code>df['a'].corr(df['b'])</code>.",
   'def corr(xs, ys):\n    n = len(xs)\n    mx, my = sum(xs) / n, sum(ys) / n\n    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys))\n    sx = sum((x - mx) ** 2 for x in xs) ** 0.5\n    sy = sum((y - my) ** 2 for y in ys) ** 0.5\n    return cov / (sx * sy)\n\nhours = [1, 2, 3, 4, 5]\nprint(round(corr(hours, [52, 55, 61, 64, 70]), 4))\nprint(round(corr(hours, [10, 8, 6, 4, 2]), 4))\nprint(corr([-2, -1, 0, 1, 2], [4, 1, 0, 1, 4]))      # a perfect U-shape', run=True,
   q=QC("The correlation between x and y is 0.0. What can you conclude?", ["There is no <b>straight-line</b> relationship; a curved one may still exist", "x and y are completely unrelated", "x causes y not to change"], 0,
        "r only measures straight-line association. The U-shape above has a perfect relationship (y = x squared) and an r of exactly 0.")),
 S("Sampling and bias",
   "You rarely see everyone, so you look at a <b>sample</b> and hope it represents the <b>population</b>. A <b>random sample</b> gives every member the same chance of being picked, so the sample is not systematically different. A <b>convenience sample</b> (the first rows, the people who reply, whoever is easy to reach) can be badly biased. Typical biases: <b>selection bias</b> (how you picked), <b>non-response bias</b> (those who answer differ from those who do not), <b>survivorship bias</b> (you only see what survived, such as companies still listed today). Here the customer list is sorted from the biggest spender down, so \"the first 10\" is a trap. (A truly random sample uses <code>random.sample</code>; we use a fixed pattern so the result never changes.)",
   'spend = list(range(100, 0, -1))      # 100 customers: 100, 99, ..., 1 (sorted, biggest first)\nprint("true mean:", sum(spend) / len(spend))\n\nfirst = spend[:10]\nprint("first 10 mean:", sum(first) / len(first))\n\nevery_tenth = spend[4::10]\nprint("every 10th mean:", sum(every_tenth) / len(every_tenth), len(every_tenth))', run=True,
   q=QC("A company emails a survey to all customers and 8 percent reply, mostly very happy or very angry ones. What is the main risk when reading the average score?", ["Non-response bias: the people who replied differ from those who did not", "The sample is too random", "The average is always wrong"], 0,
        "People who answer are not a random 8 percent. Their opinions are more extreme, so the result may not describe the customers who stayed silent.")),
 S("A/B tests: the rates, and why sample size matters",
   "An <b>A/B test</b> splits users at random into two groups, shows A to one and B to the other, and compares an outcome such as the <b>conversion rate</b> (conversions divided by users). The difference between the groups has two parts: a real effect (if any) and luck. How much does luck wobble a rate? The <b>standard error</b> of a rate is <code>sqrt(p * (1 - p) / n)</code>: roughly how far an observed rate typically lands from its true value. See how it shrinks with n: <b>4 times the users halve the wobble</b>. A gap of 2 percentage points means little if the wobble is 3 points.",
   'a_conv, a_n = 100, 1000\nb_conv, b_n = 120, 1000\npa, pb = a_conv / a_n, b_conv / b_n\nprint(pa, pb)\nprint("difference:", round(pb - pa, 4))\nprint("relative lift:", round((pb - pa) / pa, 4))\n\ndef se(p, n):\n    return (p * (1 - p) / n) ** 0.5\n\nfor n in (100, 1000, 10000):\n    print(n, round(se(0.10, n), 4))', run=True,
   q=Q("What does this show?", 'def se(p, n):\n    return (p * (1 - p) / n) ** 0.5\n\nprint(round(se(0.5, 100), 4))', ["0.05", "0.5", "0.0025"],
       "p * (1 - p) = 0.25, divided by 100 is 0.0025, and its square root is 0.05: about 5 percentage points of wobble for 100 users.")),
 S("Is the gap real? p-value and confidence interval",
   "<b>p-value</b>: the probability of seeing data <b>at least this extreme if there were no real difference</b> between A and B. It is not the probability that the result is due to chance, not the probability that B is better, and a small p does not say the effect is large. A common habit is to call p below 0.05 \"statistically significant\", which is a convention, not a law. Below we use a two-proportion z-test, which relies on a normal approximation that is fine when each group has a reasonable number of conversions and non-conversions (check a statistics text for the exact conditions). The <b>95% confidence interval</b> for the difference is <code>difference +/- 1.96 * standard error</code>: if you repeated the experiment many times, about 95% of intervals built this way would contain the true difference. Same 10% versus 12% rates, three different sample sizes:",
   'import math\n\ndef two_prop_z(xa, na, xb, nb):\n    pa, pb = xa / na, xb / nb\n    pool = (xa + xb) / (na + nb)\n    se = math.sqrt(pool * (1 - pool) * (1 / na + 1 / nb))\n    return (pb - pa) / se\n\ndef p_value(z):                       # two-sided, normal approximation\n    return math.erfc(abs(z) / math.sqrt(2))\n\nfor n in (100, 1000, 10000):\n    z = two_prop_z(n // 10, n, n * 12 // 100, n)\n    print(n, "z =", round(z, 2), "p =", f"{p_value(z):.4f}")\n\nn = 1000\npa, pb = 0.10, 0.12\nse = math.sqrt(pa * (1 - pa) / n + pb * (1 - pb) / n)\ndiff = pb - pa\nprint("95% interval:", round(diff - 1.96 * se, 4), "to", round(diff + 1.96 * se, 4))', run=True,
   q=QC("Which statement defines a p-value correctly?", ["The probability of data at least this extreme if there were no real difference", "The probability that there is no real difference", "The probability that the new version is better"], 0,
        "A p-value is computed assuming no real difference and asks how surprising the data would be. It does not give the probability of the hypothesis itself.")),
 S("Simpson's paradox",
   "Sometimes A beats B inside <b>every</b> group, yet B beats A overall. It happens when the groups are mixed in different proportions. The numbers below are invented to show it: visitors are either \"easy\" (convert often anyway) or \"hard\". Version A was shown mostly to hard visitors, version B mostly to easy ones.",
   'A = {"easy": (100, 80), "hard": (900, 270)}      # (visitors, orders)\nB = {"easy": (900, 693), "hard": (100, 25)}\n\nfor name, groups in (("A", A), ("B", B)):\n    for seg, (n, c) in groups.items():\n        print(name, seg, f"{c / n:.1%}")\n    total_n = sum(n for n, _ in groups.values())\n    total_c = sum(c for _, c in groups.values())\n    print(name, "overall", f"{total_c / total_n:.1%}")', run=True,
   q=QC("A beats B in both segments but B wins overall. What explains it?", ["The segments are mixed in different proportions: B got far more easy visitors", "The arithmetic must be wrong", "A is secretly worse"], 0,
        "The overall rate is a weighted average, and the weights differ. In a proper A/B test, random assignment makes the mix the same in both groups. Always ask what groups hide inside an average.")),
 S("The base-rate trap",
   "A fraud test catches 90 percent of frauds (<b>sensitivity</b>) and wrongly flags 5 percent of honest payments (<b>false-positive rate</b>). A payment is flagged. How likely is it fraud? Most people say about 90 percent. But the <b>base rate</b> matters: only 1 percent of payments are fraud. Count people instead of using percentages: of 10,000 payments, 100 are fraud and 9,900 are honest.",
   'people = 10000\nfraud = round(people * 0.01)          # 100\nhonest = people - fraud               # 9900\ncaught = round(fraud * 0.90)          # frauds correctly flagged\nfalse_alarms = round(honest * 0.05)   # honest payments flagged\nflagged = caught + false_alarms\nprint(caught, false_alarms, flagged)\nprint(f"chance a flagged payment is fraud: {caught / flagged:.1%}")', run=True,
   q=Q("Same test, but now half of all payments are fraud. What does this show?", 'people = 10000\nfraud = round(people * 0.50)\nhonest = people - fraud\ncaught = round(fraud * 0.90)\nfalse_alarms = round(honest * 0.05)\nprint(round(caught / (caught + false_alarms), 3))', ["0.947", "0.9", "0.154"],
       "Now 4,500 frauds are caught and only 250 honest payments are flagged: 4500 / 4750. The same test is far more trustworthy when the thing it looks for is common. Rare events produce mostly false alarms.")),
 S("Final task: compute the statistics by hand",
   "No libraries: only lists and arithmetic. This is the sort of question asked when an interviewer says \"without using pandas\". Use the exact definitions from this module: sample variance divides by <b>n - 1</b>, and the 90th percentile uses linear interpolation at position <code>(n - 1) * 0.9</code>. Round each number with <code>round(x, 4)</code>. Do not change the list you are given (sort a copy with <code>sorted</code>).",
   q=W("Write <code>summary(nums)</code> returning a dict with keys <code>n</code> (count), <code>mean</code>, <code>median</code>, <code>var</code> (sample variance, dividing by n - 1; <code>None</code> if there is only one number) and <code>p90</code> (90th percentile by linear interpolation), the last four rounded to 4 decimals. Raise <code>ValueError</code> for an empty list.",
       "def summary(nums):\n    return {}\n",
       "def summary(nums):\n    if not nums:\n        raise ValueError(\"nums is empty\")\n    xs = sorted(nums)\n    n = len(xs)\n    mean = sum(xs) / n\n    mid = n // 2\n    median = xs[mid] if n % 2 else (xs[mid - 1] + xs[mid]) / 2\n    var = None if n < 2 else sum((x - mean) ** 2 for x in xs) / (n - 1)\n    pos = (n - 1) * 0.9\n    lo = int(pos)\n    hi = min(lo + 1, n - 1)\n    p90 = xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)\n    return {\"n\": n, \"mean\": round(mean, 4), \"median\": round(median, 4), \"var\": None if var is None else round(var, 4), \"p90\": round(p90, 4)}\n",
       exprs=[("the textbook list", "summary([2, 4, 4, 4, 5, 5, 7, 9])"),
              ("unsorted odd count", "summary([9, 1, 5])"),
              ("one number", "summary([7])"),
              ("two numbers", "summary([1, 2])"),
              ("with an outlier", "summary([30, 32, 35, 36, 40, 42, 45, 300])"),
              ("negative numbers", "summary([-5, -1, 0, 3])"),
              ("the input list is not changed", "(lambda l: (summary(l)['n'], l))([3, 1, 2])"),
              ("empty list raises ValueError", "_raises(lambda: summary([]), ValueError)")],
       hint="Work on xs = sorted(nums). Median: middle item, or the average of the two middle items. Percentile: pos = (n - 1) * 0.9, lo = int(pos), then blend xs[lo] and xs[lo + 1] by the fractional part (watch the last index).",
       prelude=_RZ)),
 ])

# =====================================================================================================
# 6. MODELLING BASICS BY HAND
# =====================================================================================================
_ML_DATA = ('points = []\nfor i in range(40):\n    x = (i * 7) % 11\n    y = (i * 5) % 13\n    label = 1 if x + y >= 11 else 0\n    if i % 9 == 0:\n        label = 1 - label          # a few wrong labels: real data is noisy\n'
            '    points.append(((x, y), label))\n\ntrain = [p for i, p in enumerate(points) if i % 4 != 0]\ntest = [p for i, p in enumerate(points) if i % 4 == 0]\n')
_ML_KNN = ('import math\n\ndef predict(rows, x, k):\n    """rows is a list of (features, label). Ties between labels go to the smaller label."""\n'
           '    nearest = sorted(rows, key=lambda r: math.dist(r[0], x))[:k]\n    votes = {}\n    for _, label in nearest:\n        votes[label] = votes.get(label, 0) + 1\n    best = max(votes.values())\n'
           '    return min(label for label, v in votes.items() if v == best)\n\ndef accuracy(train_rows, eval_rows, k):\n    right = sum(1 for x, label in eval_rows if predict(train_rows, x, k) == label)\n    return right / len(eval_rows)\n\n')

PM("py-ds-ml", "Python Pro", "Modelling basics, by hand",
   "Before you trust a library to train a model, you should be able to build the idea yourself and explain why a score can lie; interviews probe exactly that.",
 [
 S("Split the data: train and test",
   "A model is judged on data it has <b>never seen</b>. So you split the rows: the <b>training set</b> is what the model learns from, the <b>test set</b> is kept aside and used once at the end to see how it does on new data. Why: a model can score perfectly on the rows it studied simply by memorising them. The data below is invented: two numbers per row (x, y) and a label 0 or 1, with a few wrong labels thrown in. The \"model\" is a pure memoriser: it looks the exact row up in the training data and guesses 0 for anything new. (We split by position to keep the page deterministic. In real work, shuffle first, for example with <code>train_test_split</code>, and for data over time split by date so you never train on the future.)",
   _ML_DATA + '\nprint(len(train), len(test))\nprint(points[:3])\n\nmemory = dict(train)               # {(x, y): label}\n\ndef accuracy(model, rows):\n    return sum(1 for x, label in rows if model(x) == label) / len(rows)\n\ndef memoriser(x):\n    return memory.get(x, 0)\n\nprint("train accuracy:", accuracy(memoriser, train))\nprint("test accuracy: ", accuracy(memoriser, test))', run=True,
   q=QC("A model scores 99% on its training rows and 70% on the held-out test rows. Which number describes how it will do on new data?", ["About 70%, the test score", "About 99%, the training score", "The average of the two"], 0,
        "The test rows play the part of future data. The training score is flattered because the model has already seen those exact rows.")),
 S("Baselines, and why accuracy can mislead",
   "Always compare a model with a dumb <b>baseline</b>, such as \"always predict the most common answer\". If you cannot beat it, the model has learned nothing. <b>Accuracy</b> is the share of correct predictions, and it hides the kind of mistake. Take 1,000 payments of which only 10 are fraud. A \"model\" that says <code>not fraud</code> every time is 99% accurate and catches nothing. A <b>confusion matrix</b> counts four outcomes, taking fraud as the <b>positive</b> class: <b>TP</b> (true positive: said fraud, was fraud), <b>FP</b> (false positive: said fraud, was honest), <b>FN</b> (false negative: missed a fraud), <b>TN</b> (true negative: said honest, was honest).",
   'y_true = [1] * 10 + [0] * 990                   # 10 frauds in 1000 payments\n\ndef counts(y_true, y_pred):\n    tp = sum(1 for t, p in zip(y_true, y_pred) if t == 1 and p == 1)\n    fp = sum(1 for t, p in zip(y_true, y_pred) if t == 0 and p == 1)\n    fn = sum(1 for t, p in zip(y_true, y_pred) if t == 1 and p == 0)\n    tn = sum(1 for t, p in zip(y_true, y_pred) if t == 0 and p == 0)\n    return tp, fp, fn, tn\n\ndef accuracy(y_true, y_pred):\n    return sum(1 for t, p in zip(y_true, y_pred) if t == p) / len(y_true)\n\nalways_no = [0] * 1000\nprint("baseline:", counts(y_true, always_no), accuracy(y_true, always_no))\n\nmodel = [1] * 6 + [0] * 4 + [1] * 12 + [0] * 978   # catches 6 frauds, 12 false alarms\nprint("model:   ", counts(y_true, model), accuracy(y_true, model))', run=True,
   q=Q("What does this show? (order is TP, FP, FN, TN)", 'y_true = [1, 0, 1, 1, 0]\ny_pred = [1, 0, 0, 1, 1]\ntp = sum(1 for t, p in zip(y_true, y_pred) if t == 1 and p == 1)\nfp = sum(1 for t, p in zip(y_true, y_pred) if t == 0 and p == 1)\nfn = sum(1 for t, p in zip(y_true, y_pred) if t == 1 and p == 0)\ntn = sum(1 for t, p in zip(y_true, y_pred) if t == 0 and p == 0)\nprint((tp, fp, fn, tn))',
       ["(2, 1, 1, 1)", "(1, 1, 2, 1)", "(2, 2, 1, 0)"], "Position by position: (1,1) TP, (0,0) TN, (1,0) FN, (1,1) TP, (0,1) FP. So TP 2, FP 1, FN 1, TN 1. Notice the real model has lower accuracy than the do-nothing baseline, yet it is the useful one.")),
 S("Precision, recall and F1",
   "<b>Precision</b> = TP / (TP + FP): of everything we flagged, how much was really positive? (High precision: few false alarms.) <b>Recall</b> = TP / (TP + FN): of all the real positives, how many did we find? (High recall: few misses.) They pull against each other: flag everything and recall is perfect while precision collapses. <b>F1</b> is their harmonic mean, <code>2 * P * R / (P + R)</code>, which is high only when both are. If a denominator is 0 (nothing flagged, or no real positives) the ratio is undefined; a common convention is to report 0.0. Which matters more depends on the cost: missing a cancer is worse than a false alarm (favour recall); sending spam to the inbox might be tolerated more than losing a real email (favour precision).",
   'tp, fp, fn = 6, 12, 4            # the fraud model from the last screen\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\nf1 = 2 * precision * recall / (precision + recall)\nprint("precision:", round(precision, 3))\nprint("recall:   ", round(recall, 3))\nprint("f1:       ", round(f1, 3))', run=True,
   q=Q("What does this show?", 'tp, fp, fn = 8, 2, 8\nprint(tp / (tp + fp), tp / (tp + fn))', ["0.8 0.5", "0.5 0.8", "0.8 0.8"],
       "Precision is 8 out of the 10 flagged. Recall is 8 out of the 16 real positives. Few false alarms, but half the positives were missed.")),
 S("k-nearest neighbours, step by step",
   "<b>k-nearest neighbours</b> (kNN) is the simplest classifier: to label a new point, find the <b>k</b> training points closest to it and take a <b>vote</b> of their labels. \"Closest\" needs a <b>distance</b>; the usual one is Euclidean, the straight-line distance <code>sqrt((a1-b1)**2 + (a2-b2)**2 + ...)</code>. There is no training step at all; the model is the data. Follow the steps for one new point:",
   'import math\nfrom collections import Counter\n\ntrain_X = [(1, 1), (2, 1), (1, 3), (6, 5), (7, 7), (8, 6)]\ntrain_y = [0, 0, 0, 1, 1, 1]\nquery = (5, 5)\n\ndef distance(a, b):\n    return math.sqrt(sum((p - q) ** 2 for p, q in zip(a, b)))\n\n# 1. distance from the query to every training point, with its label\npairs = sorted((distance(x, query), label) for x, label in zip(train_X, train_y))\nfor d, label in pairs:\n    print(round(d, 2), label)\n\n# 2. keep the k closest\nk = 5\nnearest = pairs[:k]\n\n# 3. vote\nvotes = Counter(label for _, label in nearest)\nprint(votes)\nprint("predicted label:", votes.most_common(1)[0][0])', run=True,
   q=Q("Same training data, new point (4, 4). What does this show?", 'import math\n\ntrain_X = [(1, 1), (2, 1), (1, 3), (6, 5), (7, 7), (8, 6)]\ntrain_y = [0, 0, 0, 1, 1, 1]\nq = (4, 4)\npairs = sorted((math.dist(x, q), y) for x, y in zip(train_X, train_y))\nfor k in (1, 3):\n    labels = [y for _, y in pairs[:k]]\n    print(k, max(set(labels), key=labels.count))',
       ["1 1\n3 0", "1 0\n3 0", "1 1\n3 1"], "The single closest point (6, 5) has label 1, but the next two closest are both label 0, so with k = 3 the vote flips. The choice of k changes the answer, which is the next screen.")),
 S("Overfitting and underfitting",
   "<b>Overfitting</b>: the model fits the noise in the training data, so it does great on training rows and worse on new ones. <b>Underfitting</b>: the model is too simple to capture the pattern, so it does badly on both. In kNN, k is the dial: <b>k = 1</b> copies the nearest neighbour, wrong labels included (each training point is its own nearest neighbour, so training accuracy is 100% by construction); <b>k = all rows</b> always predicts the majority class. Somewhere in between is best. Same invented data as before. Caution: this test set has only 10 rows, so each row is 10 percentage points: small test sets give jumpy scores.",
   _ML_DATA + '\n' + _ML_KNN + 'for k in (1, 3, 5, 9, 30):\n    print(f"{k:>2}  train {accuracy(train, train, k):.2f}   test {accuracy(train, test, k):.2f}")', run=True,
   q=QC("A model gets 100% on training data but only 70% on test data. What is the most likely diagnosis?", ["Overfitting: it learned the training rows including their noise", "Underfitting: the model is too simple", "The test set is too easy"], 0,
        "A big gap between training and test score is the signature of overfitting. Underfitting shows up as a low score on both.")),
 S("Feature scaling, and how leakage sneaks in",
   "kNN adds up squared differences, so a feature measured in big numbers (income in rupees) <b>swamps</b> one in small numbers (age in years). <b>Scaling</b> puts features on a similar range; <b>min-max scaling</b> uses <code>(v - lo) / (hi - lo)</code> to map to 0 to 1 (standardising, <code>(v - mean) / std</code>, is the other common choice). Now the trap: <b>data leakage</b> means information from outside the training data (the test set, or the future) slips into training, so scores look great and then collapse in production. Computing <code>lo</code> and <code>hi</code> from <b>all</b> the rows including the test rows is leakage; compute them from the training rows only, then apply the same numbers to test rows. A second classic: a column that is only known <b>after</b> the thing you predict, like <code>refund_issued</code> when predicting churn.",
   'import math\n\n# scaling statistics come from the TRAINING rows only\ntrain_age = [20, 35, 45, 60]\ntrain_income = [20000, 40000, 50000, 90000]\nlo_a, hi_a = min(train_age), max(train_age)\nlo_i, hi_i = min(train_income), max(train_income)\n\ndef scale(p):\n    age, income = p\n    return ((age - lo_a) / (hi_a - lo_a), (income - lo_i) / (hi_i - lo_i))\n\nA, B, C = (25, 50000), (60, 50500), (26, 80000)\nprint("raw:   A-B", round(math.dist(A, B), 1), " A-C", round(math.dist(A, C), 1))\nprint("scaled:A-B", round(math.dist(scale(A), scale(B)), 3), " A-C", round(math.dist(scale(A), scale(C)), 3))\n\n# a leaky feature: refund_issued is only filled in AFTER a customer cancels\nrows = [(3, 1, 1), (24, 0, 0), (5, 1, 1), (30, 0, 0), (2, 1, 1), (18, 0, 0)]   # months, refund_issued, churned\nright = sum(1 for months, refund, churned in rows if refund == churned)\nprint("accuracy using only refund_issued:", right / len(rows))', run=True,
   q=QC("You scale a feature using the mean and standard deviation of the <b>whole</b> dataset, then split into train and test. What is wrong?", ["Test-set information leaked into training through the scaling numbers", "Nothing; scaling is harmless", "Scaling only works on the test set"], 0,
        "The scaling numbers should be fitted on training rows only and then applied to test rows. Otherwise the model has had a peek at the test data, and the score is a little too good.")),
 S("Cross-validation: a steadier score",
   "One train/test split is a single roll of the dice, and a small test set is noisy. In <b>k-fold cross-validation</b> you cut the training data into k parts (<b>folds</b>), and k times: hold one fold out as validation, train on the rest, score on the held-out fold. The average of the k scores is steadier, and you can use it to choose settings such as k in kNN <b>without touching the test set</b>, which stays sealed until the very end. Below, the folds first, then the average score for each kNN k, using only the training rows.",
   _ML_DATA + '\n' + _ML_KNN + 'def folds(n, parts):\n    return [[i for i in range(n) if i % parts == f] for f in range(parts)]\n\nfor f, held in enumerate(folds(10, 5)):\n    print(f, "validate on", held)\n\ndef cv_score(rows, k, parts=5):\n    scores = []\n    for held in folds(len(rows), parts):\n        val = [rows[i] for i in held]\n        fit = [r for i, r in enumerate(rows) if i not in held]\n        scores.append(accuracy(fit, val, k))\n    return sum(scores) / parts\n\nfor k in (1, 3, 5, 9):\n    print("k =", k, "cross-validated accuracy", round(cv_score(train, k), 3))', run=True,
   q=QC("Why choose settings with cross-validation on the training data instead of repeatedly checking the test set?", ["Repeated peeking at the test set makes it part of your training process, so its score stops being honest", "The test set is too large", "Cross-validation is always faster"], 0,
        "Every time you adjust something because of the test score, the test set leaks into your decisions. Keep it for one final check.")),
 Sd("The same steps with scikit-learn",
    "In practice you use a library for the same ideas. <b>scikit-learn</b> is not available in this page, so this screen is for reading; every step below matches something you built by hand. Treat it as a map, and <b>check the sklearn docs for current signatures</b> and options before you rely on any call. Remember <code>X</code> is a table or array of features and <code>y</code> the labels.",
    'from sklearn.model_selection import train_test_split, cross_val_score\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.metrics import classification_report\n\n# split (by hand: slicing); random_state makes the shuffle repeatable\nX_train, X_test, y_train, y_test = train_test_split(\n    X, y, test_size=0.25, random_state=42, stratify=y)   # stratify keeps class shares equal\n\n# scaling + model in one pipeline, so scaling is fitted on training data only\nmodel = make_pipeline(StandardScaler(), LogisticRegression(max_iter=1000))\nmodel.fit(X_train, y_train)\npred = model.predict(X_test)\nprint(classification_report(y_test, pred))   # precision, recall, f1 per class\n\n# cross-validation (by hand: the folds loop)\nscores = cross_val_score(RandomForestClassifier(random_state=0), X_train, y_train, cv=5)\nprint(scores.mean())\n\n# the kNN you wrote has a ready-made version\nknn = KNeighborsClassifier(n_neighbors=5).fit(X_train, y_train)',
    q=QC("Why put <code>StandardScaler()</code> and the model together in a <code>make_pipeline</code> instead of scaling all of <code>X</code> first?", ["The pipeline fits the scaler on training data only, avoiding leakage, especially inside cross-validation", "Pipelines make the model more accurate by themselves", "Scaling must happen after predict"], 0,
         "Scaling all of X first uses test (and validation) rows to compute the scaling numbers. A pipeline refits the scaler on each training fold only.")),
 S("Final task: precision/recall/F1 and kNN, from scratch",
   "Two functions, no libraries beyond <code>math</code>. Build them from the definitions in this module. Edge cases are part of the grade: nothing flagged, a different positive label, ties.",
   q=W("Write two functions.<br><br><b>1.</b> <code>prf(y_true, y_pred, positive=1)</code> returns the tuple <code>(precision, recall, f1)</code>, each rounded to 3 decimals. A label counts as positive when it equals <code>positive</code>. Where a division would be by zero, that value is <code>0.0</code>.<br><br><b>2.</b> <code>knn_predict(train_X, train_y, x, k)</code>: <code>train_X</code> is a list of tuples of numbers, <code>train_y</code> the labels, <code>x</code> a tuple. Use Euclidean distance. Take the <code>k</code> closest training points (a distance tie is broken by the earlier position in the list; if <code>k</code> is bigger than the data, use all of it). Return the label with the most votes; if labels tie, return the <b>smaller</b> label.",
       "import math\n\ndef prf(y_true, y_pred, positive=1):\n    return (0.0, 0.0, 0.0)\n\ndef knn_predict(train_X, train_y, x, k):\n    return train_y[0]\n",
       "import math\n\ndef prf(y_true, y_pred, positive=1):\n    tp = sum(1 for t, p in zip(y_true, y_pred) if t == positive and p == positive)\n    fp = sum(1 for t, p in zip(y_true, y_pred) if t != positive and p == positive)\n    fn = sum(1 for t, p in zip(y_true, y_pred) if t == positive and p != positive)\n    precision = tp / (tp + fp) if tp + fp else 0.0\n    recall = tp / (tp + fn) if tp + fn else 0.0\n    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0\n    return (round(precision, 3), round(recall, 3), round(f1, 3))\n\ndef knn_predict(train_X, train_y, x, k):\n    order = sorted(range(len(train_X)), key=lambda i: math.dist(train_X[i], x))\n    votes = {}\n    for i in order[:k]:\n        votes[train_y[i]] = votes.get(train_y[i], 0) + 1\n    best = max(votes.values())\n    return min(label for label, v in votes.items() if v == best)\n",
       exprs=[("prf: a typical case", "prf([1, 0, 1, 1, 0, 0], [1, 0, 0, 1, 1, 0])"),
              ("prf: perfect predictions", "prf([1, 0, 1], [1, 0, 1])"),
              ("prf: nothing flagged, no division by zero", "prf([1, 1, 0], [0, 0, 0])"),
              ("prf: no positives anywhere", "prf([0, 0], [0, 0])"),
              ("prf: text labels with positive='spam'", "prf(['spam', 'ham', 'spam'], ['spam', 'spam', 'ham'], positive='spam')"),
              ("prf: the fraud example", "prf([1] * 10 + [0] * 990, [1] * 6 + [0] * 4 + [1] * 12 + [0] * 978)"),
              ("knn: near class 1", "knn_predict(TX, TY, (5, 5), 3)"),
              ("knn: near class 0", "knn_predict(TX, TY, (2, 2), 3)"),
              ("knn: k = 1 at (4, 4)", "knn_predict(TX, TY, (4, 4), 1)"),
              ("knn: k = 3 at (4, 4)", "knn_predict(TX, TY, (4, 4), 3)"),
              ("knn: a vote tie goes to the smaller label", "knn_predict([(0,), (10,)], [1, 0], (5,), 2)"),
              ("knn: a distance tie goes to the earlier point", "knn_predict([(0,), (2,)], [1, 0], (1,), 1)"),
              ("knn: text labels", "knn_predict([(0, 0), (1, 1), (9, 9)], ['a', 'a', 'b'], (8, 8), 1)"),
              ("knn: k bigger than the data", "knn_predict([(0,), (1,), (5,)], [0, 0, 1], (4,), 10)")],
       hint="prf: count tp, fp, fn with zip; guard each division with 'if denominator else 0.0'. knn: sort the indexes by distance, take the first k, count labels in a dict, pick the highest count (smallest label on a tie).",
       prelude="TX = [(1, 1), (2, 1), (1, 3), (6, 5), (7, 7), (8, 6)]\nTY = [0, 0, 0, 1, 1, 1]\n")),
 ])

